# Deskhand agent installer, generated by the Deskhand server at @SERVER@.
# Usage (PowerShell as Administrator):
#   irm @SERVER@/install.ps1 | iex; Install-Deskhand -Token ENROLL_TOKEN
function Install-Deskhand {
    param([Parameter(Mandatory = $true)][string]$Token)
    $ErrorActionPreference = 'Stop'
    $server = '@SERVER@'

    $me = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    if (-not $me.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'Run PowerShell as Administrator.'
    }
    if (-not [Environment]::Is64BitOperatingSystem) { throw 'Deskhand needs 64-bit Windows.' }

    $dir = Join-Path $env:ProgramFiles 'Deskhand'
    $exe = Join-Path $dir 'deskhand-agent.exe'
    $config = Join-Path $env:ProgramData 'Deskhand\agent.json'
    New-Item -ItemType Directory -Force $dir, (Split-Path $config) | Out-Null

    Get-Process deskhand-agent -ErrorAction SilentlyContinue | Stop-Process -Force
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    Write-Host "Downloading the Deskhand agent from $server"
    Invoke-WebRequest -UseBasicParsing -Uri "$server/dl/deskhand-agent-windows-x86_64.exe" -OutFile $exe

    & $exe enroll --server $server --token $Token --config $config
    if ($LASTEXITCODE -ne 0) { throw "Enrollment failed (exit $LASTEXITCODE)." }

    # TODO: register a Windows service (SYSTEM, session 0 + per-session helper) once the
    # agent's service mode exists; see docs/windows.md. Until then the agent runs in this
    # user's session and stops at sign-out.
    Start-Process -FilePath $exe -ArgumentList @('run', '--config', $config) -WindowStyle Hidden
    Write-Host "Deskhand agent installed to $exe and running."
}
